    // ══════════════════════════════════════════════════════════════
    // EXPORT PAGE (FILM-065 partial)
    // ══════════════════════════════════════════════════════════════
    async function loadExportPage() {
        if (!state.currentProject) return;
        try {
            const data = await api('/projects/' + state.currentProject.id + '/shotlist');
            const shots = data.shots || [];
            const totalMs = shots.reduce((sum, s) => sum + (s.duration_ms || 0), 0);
            document.getElementById('exportShotCount').textContent = shots.length;
            document.getElementById('exportDuration').textContent = (totalMs / 1000).toFixed(1) + 's';
        } catch (err) { setStatus('Error: ' + err.message); }
        loadDeliveryCheck();
    }

    /*
     * THE DELIVERY CHECK: every shot's selected clip, measured from the file,
     * against the project's delivery size. Free; reads files, spends nothing.
     */
    async function loadDeliveryCheck() {
        const box = document.getElementById('exportDeliveryCheck');
        if (!box || !state.currentProject) return;
        box.innerHTML = '<div class="text-sm text-muted">Measuring the selected clips…</div>';
        try {
            const r = await api('/projects/' + state.currentProject.id + '/delivery-check');
            const shots = r.shots || [];
            const bad = shots.filter(s => s.status !== 'ok');
            box.innerHTML = `
                <div class="flex-between"><strong>Delivery check</strong>
                  <button class="btn btn-sm" onclick="loadDeliveryCheck()">Measure again</button></div>
                <div class="text-sm text-muted" style="margin:4px 0 8px;">Delivers ${esc(r.asked || 'no size set')} &middot;
                  ${shots.length - bad.length} of ${shots.length} shot${shots.length === 1 ? '' : 's'} at full size</div>
                ${bad.length ? `<table class="text-sm" style="width:100%;">${bad.map(s => `<tr>
                    <td><strong>${esc(s.shot_code)}</strong></td>
                    <td>${esc(s.status === 'below' ? 'below delivery' : s.status === 'no_clip' ? 'no clip' : 'unreadable')}</td>
                    <td>${esc(s.measured || '')}</td>
                    <td class="text-muted">${esc(s.fix || '')}</td></tr>`).join('')}</table>`
                  : '<div class="text-sm">Every selected clip is at the delivery size.</div>'}`;
        } catch (err) { box.innerHTML = `<div class="text-sm" style="color:var(--danger,#c00);">Could not measure: ${esc(err.message)}</div>`; }
    }

    /*
     * PREMIERE, ONE FOLDER PER SCENE. The plan is read first (free) so the
     * question names what will be copied and what is missing; then it writes
     * into the project's Exports folder and says where.
     */
    async function exportPremiereScenes() {
        if (!state.currentProject) return;
        const box = document.getElementById('premiereScenesResult');
        const url = '/projects/' + state.currentProject.id + '/export/premiere-scenes';
        try {
            const plan = await api(url);
            const clips = (plan.scenes || []).reduce((n, s) => n + s.shots.filter(x => x.asset_id).length, 0);
            const miss = (plan.missing || []).length;
            if (!confirm(`Copy ${plan.file_count} file${plan.file_count === 1 ? '' : 's'} (${clips} clip${clips === 1 ? '' : 's'}) into ${(plan.scenes || []).length} scene folder${(plan.scenes || []).length === 1 ? '' : 's'}?`
                + (miss ? `\n${miss} item${miss === 1 ? ' is' : 's are'} missing and will be named in the READ ME.` : ''))) return;
            box.textContent = 'Copying…';
            const r = await api(url, { method: 'POST', body: '{}' });
            box.innerHTML = `Written to <code>${esc(r.dest)}</code><br>${r.copied} files, ${esc(r.xml)}`
                + (r.missing && r.missing.length ? `<br><span class="text-muted">${r.missing.length} missing, listed in READ ME.txt</span>` : '');
        } catch (err) { box.textContent = 'Could not make the folders: ' + err.message; }
    }

    /*
     * DAVINCI RESOLVE. The plan is read first (free) so the question says what
     * the first edit holds; then it writes into the project's Exports folder.
     */
    async function exportResolve() {
        if (!state.currentProject) return;
        const box = document.getElementById('resolveExportResult');
        const url = '/projects/' + state.currentProject.id + '/export/resolve';
        try {
            const plan = await api(url);
            const c = plan.counts || {};
            const miss = (plan.missing || []).length;
            if (!confirm(`Make the Resolve project: ${c.shots} shots (${c.clips} with footage, ${c.storyboard_frames} on their storyboard frame${c.gaps ? `, ${c.gaps} gap${c.gaps === 1 ? '' : 's'}` : ''}), `
                + `${c.dialogue_lines} dialogue line${c.dialogue_lines === 1 ? '' : 's'}, ${c.beds} music/ambience bed${c.beds === 1 ? '' : 's'}; ${plan.file_count} files copied.`
                + (miss ? `\n${miss} item${miss === 1 ? ' is' : 's are'} missing and will be named in the READ ME.` : ''))) return;
            box.textContent = 'Copying…';
            const r = await api(url, { method: 'POST', body: '{}' });
            box.innerHTML = `Written to <code>${esc(r.dest)}</code><br>${r.copied} files, ${esc(r.xml)}, ${esc(r.metadata)}`
                + `<br>In Resolve: copy <strong>${esc(r.script)}</strong> into Resolve's Scripts/Utility folder and run it from Workspace &gt; Scripts. The READ ME has the steps.`
                + (r.missing && r.missing.length ? `<br><span class="text-muted">${r.missing.length} missing, listed in READ ME.txt</span>` : '');
        } catch (err) { box.textContent = 'Could not make the Resolve project: ' + err.message; }
    }

    // ── Project Bundle Export/Import ─────────────────────────────
    function downloadBundle() {
        if (!state.currentProject) return;
        window.open(API() + '/projects/' + state.currentProject.id + '/bundle', '_blank');
        setStatus('Downloading project bundle...');
    }
